import{z as l,x as s,o as e,c as p,q as t,j as r,D as B,d as E,s as o,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"实盘监控与研究再触发","description":"","frontmatter":{"title":"实盘监控与研究再触发","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/live-monitoring-handoff.md","filePath":"quant/live-monitoring-handoff.md","lastUpdated":1791063341000}'),d={name:"quant/live-monitoring-handoff.md"};function C(m,a,h,f,u,D){const n=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="实盘监控与研究再触发" tabindex="-1">实盘监控与研究再触发 <a class="header-anchor" href="#实盘监控与研究再触发" aria-label="Permalink to &quot;实盘监控与研究再触发&quot;">​</a></h1><div class="epigraph"><p>衰减是公开信号的平均命运，不是运营事故；监控要回答的不是「这个月赚了没」，而是「相对预扣衰减的预算带，现在走到哪」。</p><footer>—— 据 McLean and Pontiff, Journal of Finance, 2016；Brown, Durbin and Evans, JRSS-B, 1975 整理</footer></div><p><a href="/quant/paper-to-live-staging">上一课</a>沿容量台阶把仓位放到目标档位；台阶之上，问题从「能不能上」变成「现在的 alpha 还是当初冻结的那一个吗」。本课写实盘监控的仪表、衰减检测与再研究触发器。顺序检验的方法本身——CUSUM 统计量、含衰减预算的原假设、主辅路径的错误率分配——已在<a href="/quant/live-drift-monitor">实盘漂移监测</a>讲透；本课接它留下的缺口：仪表怎么组织、每条线谁负责、报警之后如何回到研究流程而不把实盘变成新的样本内。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>监控失效有三种固定姿势。其一，盯净值：实盘路径短，净值噪声淹没信号，而且净值坏分不清是执行坏了还是 alpha 死了——把执行问题记成 alpha 死亡，下一步就会去翻本该不动的信号。其二，仪表没有 owner：人人能看、无人负责，报警发出后没有预定义动作，于是每次报警都重新开一次辩论。其三，闭环断裂：报警之后，改动绕过研究账户直接上生产——看过结果再改定义，<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>所保护的全部样本外就此消失，试验计数也失去意义。这三种姿势的共同点：监控成了展示，而不是触发器。</p><p><span class="marginnote">净值就是账户的累计盈亏曲线。直觉类比：靠它判断 alpha 死没死，像只看体温诊断疾病——发烧只说明「出了问题」，分不清是信号衰减这个病根，还是执行变差这个并发症。四条漂移线就是把「体温计」拆成专科检查，每条查一种病。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>仪表按漂移类型组织成四条线，每条对应一种病与一个责任人。<strong>alpha 线</strong>：加权 IC 与扣费后残差，相对冻结期均值加预扣衰减的预算带——带的构造见<a href="/quant/live-drift-monitor">实盘漂移监测</a>，主路径通常是这条。<strong>执行线</strong>：成交缺口对<a href="/quant/execution-cost-forecast-cap">成本预测</a>的残差，坏的是执行不是信号。<strong>拥挤线</strong>：与已部署因子及同业的滚动相关。<strong>规模线</strong>：实际占用 \\(A\\) 相对<a href="/quant/strategy-capacity-decay">策略容量与冲击衰减</a>的 \\(\\mu_{\\mathrm{net}}(A)\\) 过零点，防的是「规模漂移」——AUM 涨上去后净边缘悄悄转负。主路径穿带才停机；辅助路径穿带只降杠杆、开工单，不动仓位存量。每条线的 owner、值班表与对应动作写进 runbook：报警级别与动作一一对应，值班人执行而非判断。</p><p><span class="marginnote">规模线最常被漏装：IC 还在、缺口正常，但 AUM 已爬过 \\(\\mu_{\\mathrm{net}}(A)\\) 的过零点——策略「健康地」亏钱。容量曲线要随成交回报定期重估，报警带挂在当前版本的重估曲线上。</span></p><p><strong>再研究触发器</strong>是监控的出口：主路径停机后，系统自动在研究账户开工单，附冻结版本号、报警序列、对账与成交数据；任何参数改动都是新版本、新 \\(N\\)、重新走<a href="/quant/paper-to-live-staging">上线台阶</a>。从报警到工单应当是机器动作，不经过「谁来背锅」的会议。</p>',10)),(e(),r(i,null,{default:B(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAND%5B%22%E9%A2%84%E7%AE%97%E5%B8%A6%EF%BC%9A%E5%86%BB%E7%BB%93%E5%9D%87%E5%80%BC%2B%E9%A2%84%E6%89%A3%E8%A1%B0%E5%87%8F%22%5D%20--%3E%20C1%5B%22alpha%20%E7%BA%BF%EF%BC%9AIC%2F%E6%89%A3%E8%B4%B9%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20BAND%20--%3E%20C2%5B%22%E6%89%A7%E8%A1%8C%E7%BA%BF%EF%BC%9A%E7%BC%BA%E5%8F%A3%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20BAND%20--%3E%20C3%5B%22%E6%8B%A5%E6%8C%A4%E7%BA%BF%EF%BC%9A%E7%9B%B8%E5%85%B3%22%5D%0A%20%20BAND%20--%3E%20C4%5B%22%E8%A7%84%E6%A8%A1%E7%BA%BF%EF%BC%9AA%20%E5%AF%B9%20%CE%BC_net(A)%22%5D%0A%20%20C1%20--%3E%20M%7B%22%E4%B8%BB%E8%B7%AF%E5%BE%84%E7%A9%BF%E5%B8%A6%3F%22%7D%0A%20%20C1%20--%3E%20AUX%5B%22%E8%BE%85%E5%8A%A9%E7%A9%BF%E5%B8%A6%EF%BC%9A%E9%99%8D%E6%9D%A0%E6%9D%86%2B%E5%B7%A5%E5%8D%95%22%5D%0A%20%20C2%20--%3E%20AUX%0A%20%20C3%20--%3E%20AUX%0A%20%20C4%20--%3E%20AUX%0A%20%20M%20--%3E%7C%E5%90%A6%7C%20RUN%5B%22%E7%BB%A7%E7%BB%AD%E8%BF%90%E8%A1%8C%EF%BC%8C%E6%97%A5%E5%BF%97%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20M%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E5%81%9C%E6%9C%BA%22%5D%0A%20%20STOP%20--%3E%20TICKET%5B%22%E7%A0%94%E7%A9%B6%E8%B4%A6%E6%88%B7%E5%B7%A5%E5%8D%95%EF%BC%9A%E7%89%88%E6%9C%AC%2B%E6%95%B0%E6%8D%AE%22%5D%0A%20%20TICKET%20--%3E%20NEW%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%E3%80%81%E6%96%B0%20N%E3%80%81%E9%87%8D%E8%B5%B0%E5%8F%B0%E9%98%B6%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("闭环的机制核心是"),A("strong",null,"监控只读"),E("：监测日志只流向研究账户，不直接改生产参数；改动必须以新试验的身份重新进入晋级流程。这样 \\(N\\) 保持可数，多重检验折价继续有效，第一单元的纪律在实盘阶段没有断链。预算带防两类错：没有带，正常衰减天天误报，狼来了三次之后真死亡无人再听；带太宽，衰减实际加速（拥挤、机制变化）时漏报。顺序检验给出受控的犯错误率，这是「每天看图」永远做不到的——看图的一类错误率是每天重新抽签。")],-1)),a[5]||(a[5]=A("p",null,"数字实例能让「重新抽签」具体化：若每天按 5% 的显著性门槛看一次，一年约 250 个交易日，「至少误报一次」的概率是 \\(1 - 0.95^{250} \\approx 99.9\\%\\)——几乎必然报警。顺序检验（CUSUM 一类）的价值正在于此：它把整段监测期的总误报率控制在你预设的水平上。",-1)),(e(),r(i,null,{default:B(()=>[o(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALERT%5B%22%E5%AE%9E%E7%9B%98%E6%8A%A5%E8%AD%A6%22%5D%20--%3E%20TICKET%5B%22%E8%87%AA%E5%8A%A8%E7%94%9F%E6%88%90%E7%A0%94%E7%A9%B6%E5%B7%A5%E5%8D%95%22%5D%0A%20%20TICKET%20--%3E%20RES%5B%22%E7%A0%94%E7%A9%B6%E8%B4%A6%E6%88%B7%EF%BC%9A%E8%AF%8A%E6%96%AD%E4%B8%8E%E6%94%B9%E8%BF%9B%22%5D%0A%20%20RES%20--%3E%20VER%5B%22%E6%94%B9%E5%8A%A8%20%3D%20%E6%96%B0%E7%89%88%E6%9C%AC%20%2B%20%E6%96%B0%20N%22%5D%0A%20%20VER%20--%3E%20STAGE%5B%22%E9%87%8D%E8%B5%B0%E6%A8%A1%E6%8B%9F%E5%88%B0%E5%AE%9E%E7%9B%98%E5%8F%B0%E9%98%B6%22%5D%0A%20%20STAGE%20--%3E%20LIVE%5B%22%E9%87%8D%E6%96%B0%E9%83%A8%E7%BD%B2%E5%AE%9E%E7%9B%98%22%5D%0A%20%20RES%20-.%20%22%E7%A6%81%E6%AD%A2%EF%BC%9A%E7%9C%8B%E8%BF%87%E7%BB%93%E6%9E%9C%E7%9B%B4%E6%94%B9%E7%94%9F%E4%BA%A7%22%20.-%3E%20LIVE%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>上图是闭环的合法路径与唯一被堵死的捷径。</p><p><span class="marginnote">「监控只读」可以用邮局来类比：监测日志像只能寄往研究部门的信件，研究部门读完写好新方案，再走完整的挂号审批流程才能改地址簿；信件本身永远没有权力直接改生产参数。这条单向管道保住了「试验次数可数」，也就保住了多重检验折价的有效性。</span></p><p>规模线的机制提醒监控与研究的分工边界：容量衰减不是 alpha 漂移，处置是降规模或升级执行，不是改信号；四条线分开听，才能把病诊断对再动手。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>监控不能替代样本外验证：没有冻结期与预指定统计量的「一直在看」，只是把实盘当第三折。预算带自己也要有版本：制度切换使带失效，重估带要走与改参数相同的审批与版本号；指数调整、交易规则变化等已知跳变日应单独标记，避免机械误触发。最后，监控的价值取决于链路的完整性：报警、工单、新版本、台阶重走，任何一环断掉，仪表墙就退化为装饰——所以 runbook 与 owner 不是管理姿态，是统计纪律能落到实盘的最后一根管道。</p><p><span class="marginnote">初学者容易以为「实盘数据是最新的真数据，多看多赚」。实际上，没有冻结期与预指定统计量的「一直在看」，等于把实盘当第三折样本反复翻看——看出来的规律同样是过拟合，只不过这次过拟合发生在真金白银上，学费按亏损金额结算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>监控对象是四条漂移线（alpha、执行、拥挤、规模），不是净值；主路径穿带才停机，辅助只降杠杆。</li><li>预算带含预扣衰减，原假设不是「IC 等于回测」；顺序检验给出受控错误率，看图做不到。</li><li>每条线有 owner 与预写动作；规模线对照 \\(\\mu_{\\mathrm{net}}(A)\\)，防「健康地亏钱」。</li><li>闭环靠监控只读：停机自动生成研究工单，改动即新版本、新 \\(N\\)、重走台阶。</li><li>出处：McLean and Pontiff, <em>JF</em>, 2016；Brown, Durbin and Evans, <em>JRSS-B</em>, 1975；检验细节见<a href="/quant/live-drift-monitor">实盘漂移监测</a>，隔离原则见<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>。</li></ul>',8))])}const g=l(d,[["render",C]]);export{c as __pageData,g as default};
